// Source-bound AVX512 advisory. Every flag still requires exact confirmation.
#[repr(C)]struct RailStep{w:u32,n0:u32,n1:u32,n2:u32,nb:u32,anchor:u32}
type RailFunction=unsafe extern "C" fn(*const RailStep,usize,*const u64,usize,*mut u8)->i32;
struct RailBackend{run:RailFunction,steps:Vec<RailStep>,shadow:bool}
static RAIL_BACKEND:std::sync::OnceLock<RailBackend>=std::sync::OnceLock::new();
fn rail_flags(model:&RailAdvisory,points:&[PointTriple])->Vec<u8>{let backend=RAIL_BACKEND.get_or_init(||unsafe{let path=CString::new("/home/hclau/ecdsa_research/rail-masks-20261016/librail8_masks.so").unwrap();let handle=dlopen(path.as_ptr(),2);assert!(!handle.is_null());let f=dlsym(handle,b"rail8_population\0".as_ptr().cast());assert!(!f.is_null());assert_eq!(std::mem::size_of::<RailStep>(),24);let steps=model.steps.iter().zip(&model.anchors).map(|(s,a)|RailStep{w:s[0]as u32,n0:s[1]as u32,n1:s[2]as u32,n2:s[3]as u32,nb:s[4]as u32,anchor:*a as u32}).collect();RailBackend{run:std::mem::transmute::<*mut c_void,RailFunction>(f),steps,shadow:std::env::var_os("RAIL_SHADOW").is_some()}});let mut input=Vec::with_capacity(points.len()*8);for(t,o,e)in points{input.extend_from_slice(model.sub(t.0,o.0).as_limbs());input.extend_from_slice(model.sub(o.0,e.0).as_limbs());}let mut flags=vec![0u8;points.len()];assert_eq!(unsafe{(backend.run)(backend.steps.as_ptr(),backend.steps.len(),input.as_ptr(),points.len(),flags.as_mut_ptr())},0);if backend.shadow{for((t,o,e),flag)in points.iter().zip(&flags){assert_eq!(*flag,model.flags(*t,*o,*e),"SIMD advisory mismatch");}}flags}

fn rail_suspect_many(model:&RailAdvisory,points:&[PointTriple])->bool{rail_flags(model,points).iter().any(|x|*x!=0)}
